export type SplitOption = {
  value: string;
  label: string;
  description?: string;
  icon?: IconComponent;
};

export type SplitButtonProps = {
  options?: SplitOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onAction?: (value: string) => void | Promise<void>;
  menuLabel?: string;
  disabled?: boolean;
  className?: string;
};

const DEFAULT_SPLIT_OPTIONS: SplitOption[] = [
  {
    value: "production",
    label: "Deploy",
    description: "Build and release to production",
    icon: Rocket,
  },
  {
    value: "preview",
    label: "Deploy to preview",
    description: "A private URL for this branch",
    icon: GitBranch,
  },
  {
    value: "redeploy",
    label: "Redeploy",
    description: "Rebuild the live commit",
    icon: RotateCcw,
  },
];

export function SplitButton({
  options = DEFAULT_SPLIT_OPTIONS,
  value: controlled,
  defaultValue,
  onValueChange,
  onAction,
  menuLabel = "More deploy options",
  disabled,
  className,
}: SplitButtonProps) {
  const reduce = usePrefersReducedMotion();
  const [own, setOwn] = React.useState(defaultValue ?? options[0]?.value);
  const [open, setOpen] = React.useState(false);
  const [leaving, setLeaving] = React.useState(false);
  const [busy, setBusy] = React.useState<"idle" | "running" | "done">("idle");
  const [active, setActive] = React.useState(0);
  const root = React.useRef<HTMLDivElement>(null);
  const trigger = React.useRef<HTMLButtonElement>(null);
  const menu = React.useRef<HTMLDivElement>(null);
  const items = React.useRef<(HTMLButtonElement | null)[]>([]);
  const timer = React.useRef<number | undefined>(undefined);
  const mounted = React.useRef(true);
  const menuId = React.useId();

  const value = controlled ?? own;
  const current = options.find((o) => o.value === value) ?? options[0];
  const Icon = current?.icon;
  const group = useGlide<HTMLSpanElement>(current?.value, reduce);

  React.useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      window.clearTimeout(timer.current);
    };
  }, []);

  const hide = React.useCallback(() => {
    setOpen(false);
    setLeaving(true);
  }, []);

  React.useEffect(() => {
    if (!open) return;
    const onDown = (event: PointerEvent) => {
      if (!root.current?.contains(event.target as Node)) hide();
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [open, hide]);

  React.useEffect(() => {
    if (open) items.current[active]?.focus({ preventScroll: true });
  }, [open, active]);

  // The menu is mounted while open and while it fades out.
  React.useLayoutEffect(() => {
    const el = menu.current;
    if (!el) return;
    if (open) {
      const tween = gsap.fromTo(
        el,
        { opacity: 0, scale: reduce ? 1 : 0.96, y: reduce ? 0 : -4 },
        {
          opacity: 1,
          scale: 1,
          y: 0,
          duration: 0.18,
          ease: gEase.out,
          clearProps: "transform",
        },
      );
      return () => {
        tween.kill();
      };
    }
    if (leaving) {
      const tween = gsap.to(el, {
        opacity: 0,
        scale: reduce ? 1 : 0.97,
        duration: 0.12,
        ease: gEase.out,
        onComplete: () => setLeaving(false),
      });
      return () => {
        tween.kill();
      };
    }
  }, [open, leaving, reduce]);

  const openMenu = () => {
    setActive(Math.max(0, options.findIndex((o) => o.value === value)));
    setLeaving(false);
    setOpen(true);
  };

  const close = (refocus = true) => {
    hide();
    if (refocus) trigger.current?.focus({ preventScroll: true });
  };

  const choose = (next: string) => {
    if (controlled === undefined) setOwn(next);
    onValueChange?.(next);
    close();
  };

  const run = async () => {
    if (!current || busy === "running") return;
    setBusy("running");
    try {
      await onAction?.(current.value);
      if (!mounted.current) return;
      setBusy("done");
      window.clearTimeout(timer.current);
      timer.current = window.setTimeout(
        () => mounted.current && setBusy("idle"),
        1400,
      );
    } catch {
      if (mounted.current) setBusy("idle");
    }
  };

  const onMenuKey = (event: React.KeyboardEvent) => {
    const last = options.length - 1;
    if (event.key === "ArrowDown") setActive((i) => (i >= last ? 0 : i + 1));
    else if (event.key === "ArrowUp") setActive((i) => (i <= 0 ? last : i - 1));
    else if (event.key === "Home") setActive(0);
    else if (event.key === "End") setActive(last);
    else if (event.key === "Escape") close();
    else if (event.key === "Tab") close(false);
    else return;
    event.preventDefault();
  };

  const ink =
    "bg-primary text-primary-foreground bg-[linear-gradient(to_bottom,rgba(255,255,255,0.10),rgba(255,255,255,0)_55%)] dark:bg-[linear-gradient(to_bottom,rgba(255,255,255,0),rgba(0,0,0,0.06))]";
  const press =
    "cursor-pointer transition-[background-color,transform,scale] duration-150 ease-[cubic-bezier(0.16,1,0.3,1)] hover:bg-primary/95 active:scale-[0.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-primary-foreground/45 disabled:pointer-events-none";

  return (
    <div
      ref={root}
      className={cn(
        "relative inline-flex h-12 rounded-full keep-rounded text-[13px] font-medium",
        "shadow-[inset_0_1px_0_rgba(255,255,255,0.12),inset_0_-1px_0_rgba(0,0,0,0.08),0_0_1px_rgba(0,0,0,0.08),0_0_2px_rgba(0,0,0,0.04)] dark:shadow-[inset_0_1px_0_rgba(255,255,255,0.08),inset_0_-1px_0_rgba(0,0,0,0.08)]",
        disabled && "opacity-50",
        className,
      )}
    >
      <button
        type="button"
        disabled={disabled}
        aria-busy={busy === "running"}
        onClick={run}
        className={cn(
          "relative inline-grid place-items-center rounded-l-full keep-rounded pr-3 pl-8",
          ink,
          press,
        )}
      >
        {options.map((o) => (
          <span
            key={o.value}
            aria-hidden
            className="invisible col-start-1 row-start-1 flex items-center gap-2 whitespace-nowrap"
          >
            <span className="size-4" />
            {o.label}
          </span>
        ))}
        <span className="absolute inset-0 flex items-center justify-center">
          <span ref={group} className="flex items-center gap-2">
            <span className="grid size-4 place-items-center">
              <Presence
                id={
                  busy === "running"
                    ? "spin"
                    : busy === "done"
                      ? "done"
                      : (current?.value ?? "none")
                }
                className="col-start-1 row-start-1 grid place-items-center"
                from={{ opacity: 0, scale: reduce ? 1 : 0.6 }}
                to={{
                  opacity: 1,
                  scale: 1,
                  duration: 0.2,
                  ease: gEase.out,
                  clearProps: "transform",
                }}
                out={{ opacity: 0, scale: reduce ? 1 : 0.6, duration: 0.12 }}
              >
                {busy === "running" ? (
                  <Loader2 className="size-4 animate-spin [animation-duration:700ms]" />
                ) : busy === "done" ? (
                  <Check className="size-4" strokeWidth={2.5} />
                ) : Icon ? (
                  <Icon className="size-4" />
                ) : null}
              </Presence>
            </span>
            <span className="relative grid whitespace-nowrap">
              <Presence
                id={current?.value ?? "none"}
                popLayout
                className="col-start-1 row-start-1"
                from={{ opacity: 0, y: reduce ? 0 : 3 }}
                to={{
                  opacity: 1,
                  y: 0,
                  duration: 0.22,
                  delay: reduce ? 0 : 0.06,
                  ease: gEase.out,
                  clearProps: "transform",
                }}
                out={{
                  opacity: 0,
                  y: reduce ? 0 : -3,
                  duration: 0.12,
                  ease: gEase.out,
                }}
              >
                {current?.label}
              </Presence>
            </span>
          </span>
        </span>
      </button>

      <span aria-hidden className="w-px bg-primary-foreground/[0.2]" />

      <button
        ref={trigger}
        type="button"
        disabled={disabled}
        aria-label={menuLabel}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={menuId}
        onClick={() => (open ? close() : openMenu())}
        onKeyDown={(event) => {
          if (event.key === "ArrowDown" && !open) {
            event.preventDefault();
            openMenu();
          }
        }}
        className={cn("grid w-11 place-items-center rounded-r-full keep-rounded", ink, press)}
      >
        <span
          className="grid"
          style={{
            transform: `rotate(${open ? 180 : 0}deg)`,
            ...transition(["transform", reduce ? 0 : 240, CSS_OUT]),
          }}
        >
          <ChevronDown className="size-4" />
        </span>
      </button>

      {(open || leaving) && (
        <div
          ref={menu}
          id={menuId}
          role="menu"
          aria-label={menuLabel}
          onKeyDown={onMenuKey}
          style={{ transformOrigin: "top right" }}
          className="absolute top-full right-0 z-50 mt-1.5 w-[280px] rounded-lg border border-black/[0.045] bg-background p-1 text-foreground shadow-[0_0_0_1px_rgba(0,0,0,0.02),0_2px_4px_rgba(0,0,0,0.04),0_12px_28px_-12px_rgba(0,0,0,0.22)] dark:border-white/[0.06] dark:bg-zinc-900 dark:shadow-[0_12px_28px_-12px_rgba(0,0,0,0.7)]"
        >
          {options.map((o, i) => {
            const ItemIcon = o.icon;
            const selected = o.value === value;
            return (
              <button
                key={o.value}
                ref={(el) => {
                  items.current[i] = el;
                }}
                type="button"
                role="menuitemradio"
                aria-checked={selected}
                tabIndex={i === active ? 0 : -1}
                onClick={() => choose(o.value)}
                onPointerMove={() => setActive(i)}
                className={cn(
                  "flex w-full cursor-pointer items-start gap-2.5 rounded-md px-2.5 py-2 text-left outline-none transition-colors duration-100",
                  i === active
                    ? "bg-black/[0.045] dark:bg-white/[0.06]"
                    : "bg-transparent",
                )}
              >
                <span className="mt-px grid size-4 shrink-0 place-items-center text-muted-foreground">
                  {ItemIcon ? <ItemIcon className="size-4" /> : null}
                </span>
                <span className="min-w-0 flex-1">
                  <span className="block text-[13px] leading-5 font-medium">
                    {o.label}
                  </span>
                  {o.description && (
                    <span className="block text-[12px] leading-4 text-muted-foreground">
                      {o.description}
                    </span>
                  )}
                </span>
                <span className="mt-0.5 grid size-4 shrink-0 place-items-center">
                  {selected && <Check className="size-4" strokeWidth={2.25} />}
                </span>
              </button>
            );
          })}
        </div>
      )}

      <span className="sr-only" aria-live="polite">
        {busy === "running" ? `${current?.label}…` : busy === "done" ? "Done" : ""}
      </span>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* 8. AddToCart                                                               */
/* -------------------------------------------------------------------------- */

export type AddToCartProps = {
  price?: string;
  label?: string;
  quantity?: number;
  defaultQuantity?: number;
  onQuantityChange?: (quantity: number) => void | Promise<void>;
  max?: number;
  className?: string;
};

function CartIcon({ drops, reduce }: { drops: number; reduce: boolean }) {
  const parcel = React.useRef<HTMLSpanElement>(null);
  const cart = React.useRef<SVGSVGElement>(null);

  // A parcel falls into the basket, then the basket dips.
  React.useEffect(() => {
    const box = parcel.current;
    const basket = cart.current;
    if (!drops || reduce || !box || !basket) return;
    const timeline = gsap.timeline();
    timeline
      .set(box, { y: -11, opacity: 0, scale: 0.6 })
      .to(box, { opacity: 1, scale: 1, duration: 0.126, ease: gEase.drop }, 0)
      .to(box, { y: 4.5, duration: 0.294, ease: gEase.drop }, 0.126)
      .to(box, { opacity: 0, duration: 0.08 }, 0.42)
      .set(basket, { y: 0 }, 0)
      .to(basket, { y: 1.6, duration: 0.0992, ease: gEase.out }, 0.3844)
      .to(basket, { y: 0, duration: 0.1364, ease: gEase.out }, 0.4836);
    return () => {
      timeline.kill();
      gsap.set(box, { opacity: 0 });
      gsap.set(basket, { y: 0 });
    };
  }, [drops, reduce]);

  return (
    <span className="relative grid size-4 place-items-center">
      <span
        ref={parcel}
        aria-hidden
        className="absolute top-[1px] left-[6.5px] size-[5px] rounded-[1px] bg-current"
        style={{ opacity: 0 }}
      />
      <svg
        ref={cart}
        viewBox="0 0 16 16"
        className="size-4 overflow-visible"
        fill="none"
        aria-hidden
      >
        <path
          d="M1.5 2h1.6l1.6 8.2c.08.43.45.74.89.74h6.3c.42 0 .78-.29.88-.7L14 5H4"
          stroke="currentColor"
          strokeWidth={1.5}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <circle cx={6.2} cy={13.6} r={1.1} fill="currentColor" />
        <circle cx={11.6} cy={13.6} r={1.1} fill="currentColor" />
      </svg>
    </span>
  );
}

function CartCount({ value, reduce }: { value: number; reduce: boolean }) {
  const [previous, setPrevious] = React.useState(value);
  const [direction, setDirection] = React.useState(1);
  if (value !== previous) {
    setDirection(value > previous ? 1 : -1);
    setPrevious(value);
  }
  return (
    <span className="relative inline-grid h-[1.25em] overflow-clip tabular-nums">
      <Presence
        id={value}
        className="col-start-1 row-start-1 leading-[1.25em]"
        from={{
          yPercent: reduce ? 0 : direction * 100,
          opacity: reduce ? 0 : 1,
        }}
        to={{
          yPercent: 0,
          opacity: 1,
          duration: 0.28,
          ease: gEase.out,
          clearProps: "transform",
        }}
        out={{
          yPercent: reduce ? 0 : direction * -100,
          opacity: reduce ? 0 : 1,
          duration: 0.28,
          ease: gEase.out,
        }}
      >
        {value}
      </Presence>
    </span>
  );
}

export function AddToCart({
  price = "$48.00",
  label = "Add to cart",
  quantity: controlled,
  defaultQuantity = 0,
  onQuantityChange,
  max,
  className,
}: AddToCartProps) {
  const reduce = usePrefersReducedMotion();
  const [own, setOwn] = React.useState(defaultQuantity);
  const [drops, setDrops] = React.useState(0);
  const scope = React.useRef<HTMLDivElement>(null);
  const addButton = React.useRef<HTMLButtonElement>(null);
  const plusButton = React.useRef<HTMLButtonElement>(null);
  const minusButton = React.useRef<HTMLButtonElement>(null);
  const quantity = controlled ?? own;
  const inCart = quantity > 0;
  const atMax = max !== undefined && quantity >= max;
  const wasInCart = React.useRef(inCart);

  React.useEffect(() => {
    if (wasInCart.current === inCart) return;
    const focusedInside = scope.current?.contains(document.activeElement);
    wasInCart.current = inCart;
    if (!focusedInside) return;
    (inCart ? plusButton : addButton).current?.focus({ preventScroll: true });
  }, [inCart]);

  const change = async (next: number) => {
    const clamped = Math.max(
      0,
      max === undefined ? next : Math.min(max, next),
    );
    if (clamped === quantity) return;
    const before = quantity;
    const handOff =
      max !== undefined &&
      clamped >= max &&
      document.activeElement === plusButton.current;
    if (clamped > before) setDrops((n) => n + 1);
    if (controlled === undefined) setOwn(clamped);
    if (handOff)
      requestAnimationFrame(() =>
        minusButton.current?.focus({ preventScroll: true }),
      );
    try {
      await onQuantityChange?.(clamped);
    } catch {
      if (controlled === undefined) setOwn(before);
      if (!reduce) shake(scope.current, 4, 0.36);
    }
  };

  const step =
    "grid h-full w-11 shrink-0 cursor-pointer place-items-center text-primary-foreground hover:bg-primary-foreground/[0.06] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-primary-foreground/45 disabled:cursor-default disabled:hover:bg-transparent";

  /** Both faces stay mounted and trade places with a delayed cross-fade. */
  const face = (shown: boolean, lead: number): React.CSSProperties => ({
    opacity: shown ? 1 : 0,
    visibility: shown ? "visible" : "hidden",
    ...transition(
      ["opacity", shown ? 200 : 120, CSS_OUT, shown && !reduce ? lead : 0],
      ["visibility", 0, "linear", shown ? 0 : 120],
    ),
  });

  /** The − and + buttons slide in from the sides once the stepper shows. */
  const stepSlide = (from: number, opacity: number): React.CSSProperties => ({
    opacity: inCart ? opacity : 0,
    transform: `translateX(${inCart || reduce ? 0 : from}px)`,
    ...transition(
      ["opacity", inCart ? 320 : 120, CSS_OUT, inCart && !reduce ? 220 : 0],
      ["transform", inCart ? 320 : 120, CSS_OUT, inCart && !reduce ? 220 : 0],
      ["background-color", 150, CSS_STANDARD],
    ),
  });

  return (
    <div
      ref={scope}
      className={cn(
        "relative inline-grid h-12 overflow-clip rounded-full keep-rounded bg-primary text-sm font-medium text-primary-foreground select-none",
        "bg-[linear-gradient(to_bottom,rgba(255,255,255,0.10),rgba(255,255,255,0)_55%)] shadow-[inset_0_1px_0_rgba(255,255,255,0.12),inset_0_-1px_0_rgba(0,0,0,0.08),0_0_1px_rgba(0,0,0,0.08),0_0_2px_rgba(0,0,0,0.04)]",
        "dark:bg-[linear-gradient(to_bottom,rgba(255,255,255,0),rgba(0,0,0,0.06))] dark:shadow-[inset_0_1px_0_rgba(255,255,255,0.08),inset_0_-1px_0_rgba(0,0,0,0.08)]",
        className,
      )}
    >
      <span
        aria-hidden
        className="invisible col-start-1 row-start-1 flex items-center gap-2 px-8 whitespace-nowrap"
      >
        <span className="size-4" />
        {label}
        {price && <span className="ml-1">· {price}</span>}
      </span>

      <div
        aria-hidden={inCart}
        className="col-start-1 row-start-1 grid"
        style={face(!inCart, 140)}
      >
        <button
          ref={addButton}
          type="button"
          tabIndex={inCart ? -1 : 0}
          onClick={() => change(1)}
          aria-label={price ? `${label}, ${price}` : label}
          className="flex cursor-pointer items-center justify-center gap-2 px-8 whitespace-nowrap transition-[background-color,transform,scale] duration-150 ease-[cubic-bezier(0.16,1,0.3,1)] hover:bg-primary-foreground/[0.04] active:scale-[0.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-primary-foreground/45"
        >
          <CartIcon drops={0} reduce={reduce} />
          {label}
          {price && (
            <span className="ml-1 text-primary-foreground/65">· {price}</span>
          )}
        </button>
      </div>

      <div
        role="group"
        aria-label="Quantity in cart"
        aria-hidden={!inCart}
        className="col-start-1 row-start-1 flex items-center justify-between"
        style={face(inCart, 120)}
      >
        <button
          ref={minusButton}
          type="button"
          tabIndex={inCart ? 0 : -1}
          aria-label={quantity === 1 ? "Remove from cart" : "Remove one"}
          onClick={() => change(quantity - 1)}
          className={step}
          style={stepSlide(14, 1)}
        >
          <Minus className="size-4" strokeWidth={2} />
        </button>

        <span className="flex items-center gap-2">
          <CartIcon drops={drops} reduce={reduce} />
          <span className="flex items-center gap-1 whitespace-nowrap">
            <CartCount value={quantity} reduce={reduce} />
            <span className="leading-[1.25em] text-primary-foreground/65">
              in cart
            </span>
          </span>
        </span>

        <button
          ref={plusButton}
          type="button"
          tabIndex={inCart ? 0 : -1}
          aria-label="Add one"
          onClick={() => change(quantity + 1)}
          disabled={atMax}
          className={step}
          style={stepSlide(-14, atMax ? 0.4 : 1)}
        >
          <Plus className="size-4" strokeWidth={2} />
        </button>
      </div>

      <span className="sr-only" aria-live="polite">
        {inCart ? `${quantity} in cart` : ""}
      </span>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* 9. PaymentButton                                                           */
/* -------------------------------------------------------------------------- */

type PaymentButtonState = "idle" | "processing" | "paid" | "failed";

export type PaymentButtonProps = Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "children"
> & {
  amount?: string;
  label?: string;
  action?: () => Promise<void>;
  processingLabel?: string;
  paidLabel?: string;
  failedLabel?: string;
  failedDuration?: number;
  resetAfter?: number;
};

const paymentSlotClass =
  "invisible col-start-1 row-start-1 flex items-center justify-center gap-2 whitespace-nowrap";
const swapSlotClass = "flex items-center justify-center gap-2 whitespace-nowrap";

export const PaymentButton = React.forwardRef<
  HTMLButtonElement,
  PaymentButtonProps
>(
  (
    {
      amount = "$49.00",
      label = "Pay",
      action,
      processingLabel = "Processing",
      paidLabel = "Paid",
      failedLabel = "Payment failed",
      failedDuration = 1800,
      resetAfter,
      className,
      disabled,
      onClick,
      ...props
    },
    ref,
  ) => {
    const [state, setState] = React.useState<PaymentButtonState>("idle");
    const [attempt, setAttempt] = React.useState(0);
    const reduceMotion = usePrefersReducedMotion();
    const generation = React.useRef(0);
    const timer = React.useRef<number | undefined>(undefined);

    React.useEffect(() => {
      return () => {
        generation.current += 1;
        window.clearTimeout(timer.current);
      };
    }, []);

    const settle = (
      gen: number,
      next: PaymentButtonState,
      after?: number,
    ) => {
      setState(next);
      if (after === undefined) return;
      timer.current = window.setTimeout(() => {
        if (generation.current === gen) setState("idle");
      }, after);
    };

    const handleClick = async (event: React.MouseEvent<HTMLButtonElement>) => {
      onClick?.(event);
      if (
        event.defaultPrevented ||
        !action ||
        disabled ||
        state !== "idle"
      )
        return;

      const button = event.currentTarget;
      const gen = ++generation.current;
      setState("processing");
      try {
        await action();
        if (generation.current === gen) settle(gen, "paid", resetAfter);
      } catch {
        if (generation.current !== gen) return;
        setAttempt((n) => n + 1);
        settle(gen, "failed", failedDuration);
        if (!reduceMotion) shake(button, 4, 0.36);
      }
    };

    const idle = (
      <>
        <Lock aria-hidden className="size-4 opacity-70" strokeWidth={2.25} />
        <span>
          {label} <span className="tabular-nums">{amount}</span>
        </span>
      </>
    );
    const processing = (
      <>
        <Loader2
          aria-hidden
          className="size-4 animate-spin [animation-duration:700ms]"
        />
        {processingLabel}
      </>
    );
    const paid = (
      <>
        <Check aria-hidden className="size-4" strokeWidth={2.5} />
        {paidLabel}
      </>
    );
    const failed = (
      <>
        <CircleAlert aria-hidden className="size-4" strokeWidth={2.25} />
        {failedLabel}
      </>
    );

    return (
      <button
        ref={ref}
        type="button"
        disabled={Boolean(disabled) || state !== "idle"}
        onClick={handleClick}
        aria-busy={state === "processing"}
        data-state={state}
        className={cn(
          "relative inline-flex h-12 w-full max-w-[280px] cursor-pointer items-center justify-center overflow-hidden rounded-full keep-rounded bg-primary px-5 text-sm font-medium text-primary-foreground shadow-[inset_0_1px_0_rgba(255,255,255,0.12),inset_0_-1px_0_rgba(0,0,0,0.08),0_0_1px_rgba(0,0,0,0.08),0_0_2px_rgba(0,0,0,0.04)] dark:shadow-[inset_0_1px_0_rgba(255,255,255,0.08),inset_0_-1px_0_rgba(0,0,0,0.08)]",
          "transition-[background-color,transform,scale] duration-150 ease-[cubic-bezier(0.16,1,0.3,1)] hover:bg-primary/95 active:scale-[0.98]",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          "disabled:pointer-events-none data-[state=idle]:disabled:opacity-50",
          className,
        )}
        {...props}
      >
        <span className="grid">
          <span aria-hidden className={paymentSlotClass}>
            {idle}
          </span>
          <span aria-hidden className={paymentSlotClass}>
            {processing}
          </span>
          <span aria-hidden className={paymentSlotClass}>
            {paid}
          </span>
          <span aria-hidden className={paymentSlotClass}>
            {failed}
          </span>

          <SlideSlot
            id={state === "failed" ? `failed-${attempt}` : state}
            reduce={reduceMotion}
            className={swapSlotClass}
          >
            {state === "idle"
              ? idle
              : state === "processing"
                ? processing
                : state === "paid"
                  ? paid
                  : failed}
          </SlideSlot>
        </span>

        <span className="sr-only" aria-live="polite">
          {state === "processing"
            ? processingLabel
            : state === "paid"
              ? paidLabel
              : state === "failed"
                ? failedLabel
                : ""}
        </span>
      </button>
    );
  },
);
PaymentButton.displayName = "PaymentButton";

/* -------------------------------------------------------------------------- */
/* 10. InteractiveButton                                                      */
/* -------------------------------------------------------------------------- */

type InteractiveButtonState = "idle" | "loading" | "success";

export type InteractiveButtonProps =
  React.ButtonHTMLAttributes<HTMLButtonElement> & {
    action?: (progress: (value: number) => void) => Promise<void>;
    loadingLabel?: string;
    successLabel?: string;
    successDuration?: number;
  };

export const InteractiveButton = React.forwardRef<
  HTMLButtonElement,
  InteractiveButtonProps
>(
  (
    {
      action,
      loadingLabel = "Downloading",
      successLabel = "Downloaded",
      successDuration = 1600,
      children = "Download",
      className,
      disabled,
      onClick,
      ...props
    },
    ref,
  ) => {
    const [state, setState] = React.useState<InteractiveButtonState>("idle");
    const [percent, setPercent] = React.useState<number | null>(null);
    const reduceMotion = usePrefersReducedMotion();
    const fill = React.useRef({ value: 0 });
    const fillEl = React.useRef<HTMLSpanElement>(null);
    const generation = React.useRef(0);
    const timer = React.useRef<number | undefined>(undefined);

    const paintFill = React.useCallback(() => {
      if (fillEl.current) {
        fillEl.current.style.transform = `scaleX(${fill.current.value})`;
      }
    }, []);

    const moveFill = React.useCallback(
      (to: number, duration: number, ease: (p: number) => number = gEase.out) =>
        tweenTo(fill.current, {
          value: to,
          duration: reduceMotion ? 0 : duration,
          ease,
          onUpdate: paintFill,
        }),
      [reduceMotion, paintFill],
    );

    React.useEffect(() => {
      const values = fill.current;
      return () => {
        generation.current += 1;
        window.clearTimeout(timer.current);
        gsap.killTweensOf(values);
      };
    }, []);

    const handleClick = async (event: React.MouseEvent<HTMLButtonElement>) => {
      onClick?.(event);
      if (event.defaultPrevented || !action || disabled || state !== "idle")
        return;

      const gen = ++generation.current;
      let determinate = false;
      gsap.killTweensOf(fill.current);
      fill.current.value = 0;
      paintFill();
      setPercent(null);
      setState("loading");
      void moveFill(0.9, 3.2, gEase.creep);

      const report = (value: number) => {
        if (generation.current !== gen) return;
        const clamped = Math.min(1, Math.max(0, value));
        determinate = true;
        setPercent(Math.round(clamped * 100));
        void moveFill(clamped, 0.3);
      };

      try {
        await action(report);
        if (generation.current !== gen) return;
        if (determinate) setPercent(100);
        await moveFill(1, 0.28);
        if (generation.current !== gen) return;
        setState("success");
        timer.current = window.setTimeout(() => {
          if (generation.current !== gen) return;
          setState("idle");
          void moveFill(0, 0.2);
        }, successDuration);
      } catch {
        if (generation.current !== gen) return;
        setState("idle");
        void moveFill(0, 0.2);
      }
    };

    const idleLabel = (
      <>
        <Download
          aria-hidden
          className="size-4 transition-transform duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] group-hover:translate-y-0.5"
        />
        {children}
      </>
    );
    const loadingText = (value: number | null) => (
      <>
        {loadingLabel}
        {value !== null && (
          <span className="inline-block w-[4ch] text-left tabular-nums text-muted-foreground">
            {value}%
          </span>
        )}
      </>
    );
    const successText = (
      <>
        <Check aria-hidden className="size-4" strokeWidth={2.5} />
        {successLabel}
      </>
    );

    return (
      <button
        ref={ref}
        type="button"
        disabled={Boolean(disabled) || state !== "idle"}
        onClick={handleClick}
        aria-busy={state === "loading"}
        data-state={state}
        className={cn(
          "group relative inline-flex h-12 cursor-pointer items-center justify-center overflow-hidden rounded-full keep-rounded border border-black/[0.045] bg-white px-5 text-sm font-medium text-foreground shadow-[inset_0_1px_0_rgba(255,255,255,0.9),0_0_1px_rgba(0,0,0,0.05),0_0_1px_rgba(0,0,0,0.03)] dark:border-white/[0.06] dark:bg-background dark:shadow-[inset_0_1px_0_rgba(255,255,255,0.06),0_0_1px_rgba(0,0,0,0.2),0_0_1px_rgba(0,0,0,0.12)]",
          "transition-[background-color,transform,scale] duration-150 ease-[cubic-bezier(0.16,1,0.3,1)] hover:bg-black/[0.03] active:scale-[0.98] dark:hover:bg-white/[0.035]",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          "disabled:pointer-events-none data-[state=idle]:disabled:opacity-50",
          className,
        )}
        {...props}
      >
        <span
          ref={fillEl}
          aria-hidden
          style={{ transform: "scaleX(0)" }}
          className="pointer-events-none absolute inset-0 origin-left bg-foreground/[0.07]"
        />

        <span className="relative grid">
          <span aria-hidden className={paymentSlotClass}>
            {idleLabel}
          </span>
          <span aria-hidden className={paymentSlotClass}>
            {loadingText(100)}
          </span>
          <span aria-hidden className={paymentSlotClass}>
            {successText}
          </span>

          <SlideSlot
            id={
              state === "loading"
                ? percent === null
                  ? "loading"
                  : "progress"
                : state
            }
            reduce={reduceMotion}
            className={swapSlotClass}
          >
            {state === "idle"
              ? idleLabel
              : state === "loading"
                ? loadingText(percent)
                : successText}
          </SlideSlot>
        </span>

        <span className="sr-only" aria-live="polite">
          {state === "loading"
            ? loadingLabel
            : state === "success"
              ? successLabel
              : ""}
        </span>
      </button>
    );
  },
);
InteractiveButton.displayName = "InteractiveButton";

/* -------------------------------------------------------------------------- */
/* 11. SlideToConfirm                                                         */
/* -------------------------------------------------------------------------- */

type SlideState = "idle" | "dragging" | "pending" | "done";

export type SlideToConfirmProps = {
  action?: () => Promise<void>;
  label?: string;
  pendingLabel?: string;
  doneLabel?: string;
  errorLabel?: string;
  threshold?: number;
  resetAfter?: number;
  disabled?: boolean;
  className?: string;
};

const SLIDE_HEIGHT = 48;
const SLIDE_INSET = 4;
const SLIDE_THUMB = 40;

export function SlideToConfirm({
  action,
  label = "Slide to deploy",
  pendingLabel = "Deploying",
  doneLabel = "Deployed",
  errorLabel = "Couldn't deploy",
  threshold = 0.9,
  resetAfter,
  disabled,
  className,
}: SlideToConfirmProps) {
  const [state, setState] = React.useState<SlideState>("idle");
  const [error, setError] = React.useState(false);
  const [width, setWidth] = React.useState(0);
  const [value, setValue] = React.useState(0);
  const reduce = usePrefersReducedMotion();
  const track = React.useRef<HTMLDivElement>(null);
  const thumbEl = React.useRef<HTMLButtonElement>(null);
  const fillEl = React.useRef<HTMLDivElement>(null);
  const radius = useElementRadius(track);
  const drag = React.useRef<{
    id: number;
    startX: number;
    origin: number;
    moved: boolean;
    at: number;
  } | null>(null);
  const timer = React.useRef<number | undefined>(undefined);
  const mounted = React.useRef(true);
  // The thumb's offset from its resting place, in px.
  const thumb = React.useRef({ x: 0 });
  const target = React.useRef(0);

  const r = Math.min(radius, SLIDE_HEIGHT / 2);
  const max = Math.max(0, width - SLIDE_THUMB - SLIDE_INSET * 2);

  /** Puts the thumb and the ink that trails it where `thumb.x` says. */
  const paint = React.useCallback(() => {
    const x = thumb.current.x;
    if (thumbEl.current) thumbEl.current.style.transform = `translateX(${x}px)`;
    if (fillEl.current) {
      const reach = Math.max(0, width - (x + SLIDE_THUMB + SLIDE_INSET * 2));
      fillEl.current.style.clipPath = `inset(0px ${reach}px 0px 0px round ${r}px)`;
      fillEl.current.style.opacity = String(Math.min(1, Math.max(0, x / 16)));
    }
  }, [width, r]);

  React.useLayoutEffect(() => {
    paint();
  }, [paint, width]);

  React.useEffect(() => {
    mounted.current = true;
    const values = thumb.current;
    return () => {
      mounted.current = false;
      gsap.killTweensOf(values);
      window.clearTimeout(timer.current);
    };
  }, []);

  React.useEffect(() => {
    const el = track.current;
    if (!el) return;
    const measure = () => setWidth(el.offsetWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const busy = state === "pending" || state === "done";

  const slideTo = (to: number, vars: gsap.TweenVars) =>
    tweenTo(thumb.current, { x: to, onUpdate: paint, ...vars });

  const sendBack = () => {
    setValue(0);
    target.current = 0;
    void slideTo(
      0,
      reduce ? { duration: 0 } : { duration: SPRING_RETURN.duration, ease: SPRING_RETURN.ease },
    );
  };

  const confirm = async () => {
    setState("pending");
    setValue(100);
    setError(false);
    await slideTo(max, { duration: reduce ? 0 : 0.18, ease: gEase.out });
    if (!mounted.current) return;
    if ("vibrate" in navigator) navigator.vibrate?.(12);
    try {
      await action?.();
      if (!mounted.current) return;
      setState("done");
      if (resetAfter !== undefined) {
        timer.current = window.setTimeout(() => {
          if (!mounted.current) return;
          setState("idle");
          sendBack();
        }, resetAfter);
      }
    } catch {
      if (!mounted.current) return;
      setState("idle");
      sendBack();
      setError(true);
      window.clearTimeout(timer.current);
      timer.current = window.setTimeout(
        () => mounted.current && setError(false),
        1800,
      );
    }
  };

  const nudge = async () => {
    if (reduce) return;
    await slideTo(Math.min(28, max), { duration: 0.22, ease: gEase.out });
    void slideTo(0, {
      duration: SPRING_RETURN.duration,
      ease: SPRING_RETURN.ease,
    });
  };

  const onPointerDown = (event: React.PointerEvent<HTMLButtonElement>) => {
    if (disabled || busy || event.button !== 0) return;
    event.currentTarget.setPointerCapture(event.pointerId);
    gsap.killTweensOf(thumb.current);
    drag.current = {
      id: event.pointerId,
      startX: event.clientX,
      origin: thumb.current.x,
      moved: false,
      at: performance.now(),
    };
    target.current = thumb.current.x;
    setState("dragging");
  };

  const onPointerMove = (event: React.PointerEvent<HTMLButtonElement>) => {
    const d = drag.current;
    if (!d || d.id !== event.pointerId) return;
    const dx = event.clientX - d.startX;
    if (Math.abs(dx) > 3) d.moved = true;
    thumb.current.x = Math.min(max, Math.max(0, d.origin + dx));
    paint();
  };

  const onPointerUp = (event: React.PointerEvent<HTMLButtonElement>) => {
    const d = drag.current;
    if (!d || d.id !== event.pointerId) return;
    drag.current = null;
    if (max && thumb.current.x / max >= threshold) {
      void confirm();
      return;
    }
    setState("idle");
    if (!d.moved && performance.now() - d.at < 400) {
      void nudge();
      return;
    }
    sendBack();
  };

  const onKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    if (disabled || busy) return;
    const step = max / 5;
    let next: number | null = null;
    if (event.key === "ArrowRight" || event.key === "ArrowUp")
      next = target.current + step;
    if (event.key === "ArrowLeft" || event.key === "ArrowDown")
      next = target.current - step;
    if (event.key === "Home") next = 0;
    if (event.key === "End" || event.key === "Enter" || event.key === " ")
      next = max;
    if (next === null) return;
    event.preventDefault();
    const clamped = Math.min(max, Math.max(0, next));
    if (max && clamped / max >= threshold) {
      void confirm();
      return;
    }
    target.current = clamped;
    setValue(Math.round((clamped / (max || 1)) * 100));
    void slideTo(clamped, { duration: reduce ? 0 : 0.2, ease: gEase.out });
  };

  const measured = width > 0;
  const restText = error ? errorLabel : label;
  const restId = busy ? null : restText;
  const progressId = state === "pending" || state === "done" ? state : null;

  return (
    <div
      ref={track}
      data-state={state}
      className={cn(
        "relative w-[320px] max-w-full overflow-clip rounded-full keep-rounded text-sm font-medium select-none",
        "has-[[role=slider]:focus-visible]:outline-solid has-[[role=slider]:focus-visible]:outline-2 has-[[role=slider]:focus-visible]:outline-offset-2 has-[[role=slider]:focus-visible]:outline-ring/50",
        "border border-black/[0.04] bg-black/[0.035] shadow-[inset_0_0_2px_rgba(0,0,0,0.06)] dark:border-white/[0.05] dark:bg-white/[0.04] dark:shadow-[inset_0_0_2px_rgba(0,0,0,0.5)]",
        disabled && "opacity-50",
        className,
      )}
      style={{ height: SLIDE_HEIGHT }}
    >
      <span
        aria-hidden
        className="pointer-events-none absolute inset-y-0 right-0 grid place-items-center text-muted-foreground"
        style={{ left: SLIDE_THUMB + SLIDE_INSET * 2 }}
      >
        <SlideSlot
          id={restId}
          reduce={reduce}
          className={cn(
            "whitespace-nowrap",
            error && "text-red-600 dark:text-red-400",
          )}
        >
          {restText}
        </SlideSlot>
      </span>

      {measured && (
        <div
          ref={fillEl}
          aria-hidden
          className="pointer-events-none absolute inset-0 bg-primary bg-[linear-gradient(to_bottom,rgba(255,255,255,0.08),rgba(255,255,255,0)_60%)] dark:bg-[linear-gradient(to_bottom,rgba(255,255,255,0),rgba(0,0,0,0.06))]"
        >
          <span
            className="absolute inset-y-0 right-0 grid place-items-center text-primary-foreground"
            style={{ left: SLIDE_THUMB + SLIDE_INSET * 2 }}
          >
            <SlideSlot id={restId} reduce={reduce} className="whitespace-nowrap">
              {restText}
            </SlideSlot>
          </span>
        </div>
      )}

      <span
        aria-hidden
        className="pointer-events-none absolute inset-y-0 left-0 grid place-items-center text-primary-foreground"
        style={{ right: SLIDE_THUMB + SLIDE_INSET * 2 }}
      >
        <SlideSlot
          id={progressId}
          reduce={reduce}
          className="whitespace-nowrap"
        >
          {state === "pending" ? pendingLabel : doneLabel}
        </SlideSlot>
      </span>

      <button
        ref={thumbEl}
        type="button"
        role="slider"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={value}
        aria-valuetext={
          state === "pending"
            ? pendingLabel
            : state === "done"
              ? doneLabel
              : `${value}%`
        }
        aria-disabled={disabled || busy}
        disabled={disabled}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        onKeyDown={onKeyDown}
        onContextMenu={(event) => event.preventDefault()}
        style={{
          width: SLIDE_THUMB,
          top: SLIDE_INSET,
          bottom: SLIDE_INSET,
          left: SLIDE_INSET,
        }}
        className={cn(
          "group absolute grid touch-none place-items-center rounded-full keep-rounded bg-background text-foreground",
          "shadow-[inset_0_1px_0_rgba(255,255,255,0.9),0_0_0_1px_rgba(0,0,0,0.04),0_0_1px_rgba(0,0,0,0.06),0_0_2px_rgba(0,0,0,0.04)] dark:bg-zinc-800 dark:text-zinc-100 dark:shadow-[inset_0_1px_0_rgba(255,255,255,0.08),0_0_0_1px_rgba(255,255,255,0.06),0_0_1px_rgba(0,0,0,0.3),0_0_1px_rgba(0,0,0,0.2)]",
          "transition-shadow duration-150 focus-visible:outline-none",
          busy
            ? "cursor-default"
            : state === "dragging"
              ? "cursor-grabbing"
              : "cursor-grab",
        )}
      >
        <span className="grid size-4 place-items-center">
          <SlideSlot
            id={!busy ? "arrow" : state}
            reduce={reduce}
            className="grid place-items-center"
          >
            {!busy ? (
              <ArrowRight className="size-4 transition-transform duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] group-hover:translate-x-0.5" />
            ) : state === "pending" ? (
              <Loader2 className="size-4 animate-spin [animation-duration:700ms]" />
            ) : (
              <PopIn
                reduce={reduce}
                from={POP_FROM}
                className="grid place-items-center"
              >
                <Check className="size-4" strokeWidth={2.5} />
              </PopIn>
            )}
          </SlideSlot>
        </span>
      </button>

      <span className="sr-only" aria-live="polite">
        {state === "pending"
          ? pendingLabel
          : state === "done"
            ? doneLabel
            : error
              ? errorLabel
              : ""}
      </span>
    </div>
  );
}

import gsap from "gsap";
import { cubicBezier, type FrameTicker } from "./motion-curves";

/**
 * GSAP-side glue for the GSAP builds of components that also ship a Motion
 * Motion twin. Kept apart from motion-curves.ts so the library-free curves
 * never pull GSAP into a CSS or Motion build.
 */

/** `gsap.ticker` as a FrameTicker, so spring followers run on GSAP's loop. */
export const gsapTicker: FrameTicker = {
  add(callback) {
    const tick = (_time: number, deltaTime: number) => callback(deltaTime);
    gsap.ticker.add(tick);
    return () => gsap.ticker.remove(tick);
  },
};

/** A Motion / CSS cubic-bezier array as a GSAP ease. */
export const bezierEase = (curve: readonly [number, number, number, number] | readonly number[]) =>
  cubicBezier(curve[0], curve[1], curve[2], curve[3]);

/** `(prefers-reduced-motion: reduce)` right now. */
export const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;

/**
 * Motion curves with no animation library behind them.
 *
 * The components here ship as CSS, GSAP or Motion builds that must move
 * identically, so the curves are computed once, from the same numbers, and
 * handed to whichever engine runs them:
 *
 *   - `cubicBezier(x1, y1, x2, y2)` → an easing function (GSAP accepts any
 *     `(progress) => value` as `ease`), exact for Motion's `ease: [..]` arrays
 *     and for CSS `cubic-bezier()`.
 *   - `spring({ stiffness, damping, mass })` → the analytic solution Motion
 *     Motion uses, as an easing function plus the time it takes to settle, or
 *     as a CSS `linear()` string for a fixed start and end.
 *   - `createSpringFollower` → a value that chases a moving target through the
 *     same spring every frame, like Motion's `useSpring`, for pointer-driven
 *     motion that no fixed curve can describe.
 */

// ---------------------------------------------------------------------------
// Cubic bezier
// ---------------------------------------------------------------------------

/**
 * The CSS / Motion cubic-bezier as a function of progress. Newton-Raphson
 * with a bisection fallback, the same solver browsers use.
 */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  if (x1 === y1 && x2 === y2) return (t: number) => t;

  const a = (p1: number, p2: number) => 1 - 3 * p2 + 3 * p1;
  const b = (p1: number, p2: number) => 3 * p2 - 6 * p1;
  const c = (p1: number) => 3 * p1;
  const at = (t: number, p1: number, p2: number) =>
    ((a(p1, p2) * t + b(p1, p2)) * t + c(p1)) * t;
  const slope = (t: number, p1: number, p2: number) =>
    3 * a(p1, p2) * t * t + 2 * b(p1, p2) * t + c(p1);

  const solveX = (x: number) => {
    let t = x;
    for (let i = 0; i < 8; i++) {
      const s = slope(t, x1, x2);
      if (Math.abs(s) < 1e-6) break;
      const err = at(t, x1, x2) - x;
      if (Math.abs(err) < 1e-7) return t;
      t -= err / s;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 30 && hi - lo > 1e-7; i++) {
      const value = at(t, x1, x2);
      if (value < x) lo = t;
      else hi = t;
      t = (lo + hi) / 2;
    }
    return t;
  };

  return (x: number) => (x <= 0 ? 0 : x >= 1 ? 1 : at(solveX(x), y1, y2));
}

/** Motion's named eases, as the cubic-beziers they are. */
export const MOTION_EASE = {
  linear: [0, 0, 1, 1],
  easeIn: [0.42, 0, 1, 1],
  easeOut: [0, 0, 0.58, 1],
  easeInOut: [0.42, 0, 0.58, 1],
  circIn: [0.55, 0, 1, 0.45],
  circOut: [0.55, 0, 0.45, 1],
  circInOut: [0.85, 0, 0.15, 1],
  backIn: [0.31, 0.01, 0.66, -0.59],
  backOut: [0.33, 1.53, 0.69, 0.99],
  anticipate: [0.66, -0.56, 0.34, 1.35],
} as const;

/**
 * Motion's default layout transition (`layout` / `layoutId`):
 * `{ duration: 0.45, ease: [0.4, 0, 0.1, 1] }`.
 */
export const LAYOUT_TRANSITION = { duration: 0.45, ease: [0.4, 0, 0.1, 1] as const };

// ---------------------------------------------------------------------------
// Spring
// ---------------------------------------------------------------------------

export interface SpringOptions {
  /** Motion default 100. */
  stiffness?: number;
  /** Motion default 10. */
  damping?: number;
  /** Motion default 1. */
  mass?: number;
  /** Starting velocity, in units of the whole distance per second. */
  velocity?: number;
  /** How close to the end counts as settled, as a fraction of the distance. */
  restDelta?: number;
}

/**
 * Normalised position (0 → 1) of a spring released from 0 towards 1, at time
 * `t` seconds. The closed-form solution Motion's `spring()` generator
 * uses for the under-, critically and over-damped cases.
 */
export function springAt(options: SpringOptions = {}) {
  const { stiffness = 100, damping = 10, mass = 1, velocity = 0 } = options;
  const zeta = damping / (2 * Math.sqrt(stiffness * mass));
  const omega0 = Math.sqrt(stiffness / mass);
  // Motion's convention: distance still to cover, velocity toward it negated.
  const delta = 1;
  const v0 = -velocity;

  if (zeta < 1) {
    const omegaD = omega0 * Math.sqrt(1 - zeta * zeta);
    return (t: number) => {
      const envelope = Math.exp(-zeta * omega0 * t);
      return (
        1 -
        envelope *
          (((v0 + zeta * omega0 * delta) / omegaD) * Math.sin(omegaD * t) +
            delta * Math.cos(omegaD * t))
      );
    };
  }
  if (zeta === 1) {
    return (t: number) => 1 - Math.exp(-omega0 * t) * (delta + (v0 + omega0 * delta) * t);
  }
  const omegaD = omega0 * Math.sqrt(zeta * zeta - 1);
  return (t: number) => {
    const envelope = Math.exp(-zeta * omega0 * t);
    const freq = Math.min(omegaD * t, 300);
    return (
      1 -
      (envelope *
        ((v0 + zeta * omega0 * delta) * Math.sinh(freq) + omegaD * delta * Math.cosh(freq))) /
        omegaD
    );
  };
}

/** Seconds until the spring stays within `restDelta` of its end. */
export function springDuration(options: SpringOptions = {}) {
  const at = springAt(options);
  const restDelta = options.restDelta ?? 0.001;
  const step = 1 / 240;
  let lastOutside = 0;
  for (let t = 0; t <= 10; t += step) {
    if (Math.abs(1 - at(t)) > restDelta) lastOutside = t;
    else if (t - lastOutside > 0.1) break;
  }
  return Math.max(lastOutside + step, step);
}

/**
 * A spring as a duration and an easing function over it — what GSAP takes:
 *
 *   const { duration, ease } = springEase({ stiffness: 300, damping: 20 });
 *   gsap.to(el, { y: 0, duration, ease });
 *
 * Exact for a fixed start and end; a spring that has to react mid-flight to a
 * new target needs `createSpringFollower` instead.
 */
export function springEase(options: SpringOptions = {}) {
  const duration = springDuration(options);
  const at = springAt(options);
  return {
    duration,
    ease: (progress: number) => (progress >= 1 ? 1 : at(progress * duration)),
  };
}

/**
 * A spring as a CSS `linear()` easing and its duration in ms, for
 * `transition` / `animation` with a fixed start and end.
 *
 *   const { easing, duration } = springLinear({ stiffness: 400, damping: 30 });
 *   el.style.transition = `transform ${duration}ms ${easing}`;
 */
export function springLinear(options: SpringOptions = {}, pointsPerSecond = 60) {
  const duration = springDuration(options);
  const at = springAt(options);
  const count = Math.max(Math.ceil(duration * pointsPerSecond), 8);
  const points: string[] = [];
  for (let i = 0; i <= count; i++) {
    const t = (i / count) * duration;
    points.push(String(Math.round((i === count ? 1 : at(t)) * 10000) / 10000));
  }
  return { easing: `linear(${points.join(", ")})`, duration: Math.round(duration * 1000) };
}

// ---------------------------------------------------------------------------
// Spring follower (useSpring equivalent)
// ---------------------------------------------------------------------------

/** Something that calls back once per frame with the time since the last, in ms. */
export interface FrameTicker {
  add: (callback: (deltaMs: number) => void) => () => void;
}

/** requestAnimationFrame as a ticker — the library-free default. */
export const rafTicker: FrameTicker = {
  add(callback) {
    let last = performance.now();
    let frame = requestAnimationFrame(function tick(now) {
      callback(now - last);
      last = now;
      frame = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(frame);
  },
};

export interface SpringFollower {
  /** Chase a new target from wherever the value is now, keeping its velocity. */
  set: (target: number) => void;
  /** Move to a value instantly, with no motion. */
  jump: (value: number) => void;
  get: () => number;
  destroy: () => void;
}

/**
 * A value that follows its target through a spring, integrating the same
 * equation of motion Motion's `useSpring` solves — so a pointer-driven spring
 * reads the same in every build. Runs only while moving; `onUpdate` receives
 * each new value.
 */
export function createSpringFollower(
  initial: number,
  onUpdate: (value: number) => void,
  options: SpringOptions & { restSpeed?: number; ticker?: FrameTicker } = {},
): SpringFollower {
  const { stiffness = 100, damping = 10, mass = 1, ticker = rafTicker } = options;
  const restDelta = options.restDelta ?? 0.01;
  const restSpeed = options.restSpeed ?? 0.01;
  let value = initial;
  let target = initial;
  let velocity = 0;
  let stop: (() => void) | null = null;

  const step = (deltaMs: number) => {
    // Fixed 1ms sub-steps keep the integration stable for stiff springs and
    // independent of the frame rate.
    const steps = Math.min(Math.max(Math.round(deltaMs), 1), 250);
    for (let i = 0; i < steps; i++) {
      const force = -stiffness * (value - target) - damping * velocity;
      velocity += (force / mass) * 0.001;
      value += velocity * 0.001;
    }
    if (Math.abs(target - value) < restDelta && Math.abs(velocity) < restSpeed) {
      value = target;
      velocity = 0;
      stop?.();
      stop = null;
    }
    onUpdate(value);
  };

  return {
    set(next) {
      target = next;
      if (!stop && value !== target) stop = ticker.add(step);
    },
    jump(next) {
      stop?.();
      stop = null;
      value = target = next;
      velocity = 0;
      onUpdate(value);
    },
    get: () => value,
    destroy() {
      stop?.();
      stop = null;
    },
  };
}

"use client";

/**
 * Animated icons: the Lucide glyph set, each with a short hand-tuned motion that
 * plays when the control around it is hovered or focused (or when it first
 * appears, for state-change icons such as a check).
 *
 * Dependency-free on purpose. Motion runs on the Web Animations API, so the icons
 * work in any component whatever animation library it uses (GSAP or Motion),
 * add no npm package, and stand still under `prefers-reduced-motion`.
 *
 * Use them exactly like Lucide icons:
 *   <ChevronDownIcon className="size-4" />
 * They animate with the closest button, link, tab, menu item or label, or on
 * their own hover when there is none. Pass `animated={false}` to keep one still,
 * `animateOnMount` to play it once as it appears.
 *
 * To add an icon, copy its node list from lucide-react (`__iconData.node`) into a
 * `defineIcon(...)` call with the preset that suits it (see DESIGN.md, Icons).
 */
import {
  createElement,
  forwardRef,
  useCallback,
  useEffect,
  useRef,
  type ComponentType,
  type SVGProps,
} from "react";
import { prefersReducedMotion } from "@/lib/animate";
import { cn } from "@/lib/utils";

export type IconProps = Omit<SVGProps<SVGSVGElement>, "ref"> & {
  size?: number | string;
  strokeWidth?: number | string;
  /** Play the motion on hover or focus. Default true. */
  animated?: boolean;
  /** Also play it once when the icon mounts, for icons that mark a state change. */
  animateOnMount?: boolean;
};

/** Anything that renders like an icon: these, or a Lucide icon. */
export type IconComponent = ComponentType<IconProps>;

type IconNode = [tag: string, attrs: Record<string, string>][];

const SOFT = "cubic-bezier(0.22, 1, 0.36, 1)";

const move = (x: string, y = "0") => `translate(${x}, ${y})`;

type Preset = {
  frames: Keyframe[];
  duration: number;
  /** Draw each shape in with a stroke instead of moving the whole icon. */
  draw?: boolean;
};

const PRESETS = {
  nudgeRight: { duration: 650, frames: [{ transform: move("0") }, { transform: move("18%") }, { transform: move("0") }] },
  nudgeLeft: { duration: 650, frames: [{ transform: move("0") }, { transform: move("-18%") }, { transform: move("0") }] },
  nudgeUp: { duration: 650, frames: [{ transform: move("0") }, { transform: move("0", "-18%") }, { transform: move("0") }] },
  nudgeDown: { duration: 650, frames: [{ transform: move("0") }, { transform: move("0", "18%") }, { transform: move("0") }] },
  float: { duration: 700, frames: [{ transform: move("0") }, { transform: move("14%", "-14%") }, { transform: move("0") }] },
  spin: { duration: 800, frames: [{ transform: "rotate(0deg)" }, { transform: "rotate(360deg)" }] },
  spinBack: { duration: 800, frames: [{ transform: "rotate(0deg)" }, { transform: "rotate(-360deg)" }] },
  spinSlow: { duration: 1200, frames: [{ transform: "rotate(0deg)" }, { transform: "rotate(180deg)" }] },
  wiggle: {
    duration: 750,
    frames: [0, -14, 12, -8, 4, 0].map((deg) => ({ transform: `rotate(${deg}deg)` })),
  },
  shake: {
    duration: 520,
    frames: [0, -9, 9, -6, 6, 0].map((x) => ({ transform: move(`${x}%`) })),
  },
